// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    Maker1271 maker;
    MockERC20 token;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        maker = new Maker1271();
        token = new MockERC20();
    }

    function testFuzz_property(
        uint256 duration,
        uint256 strike,
        uint256 premium,
        address taker,
        bytes calldata signature
    ) public {
        // wide admissible domain
        duration = bound(duration, 1 days, 9_000 days);
        strike = bound(strike, 1, 1e30);
        premium = bound(premium, 1, 1e30);
        vm.assume(taker != address(0));
        vm.assume(signature.length != 65); // force the ERC-1271 path deterministically

        // long put order
        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: false,
            isLong: true,
            baseAsset: address(token),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1 days,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256[] memory noFloorIds = new uint256[](0);

        vm.prank(taker);
        try c.fillOrder(order, signature, noFloorIds) {
            // fill succeeded
        } catch {
            fail();
        }

        // RULE: the owner of a long position filled at the current time must be able
        // to exercise it (the expiration is recorded so the position is NOT expired).
        vm.prank(address(maker));
        bool ok;
        try c.exercise(order, noFloorIds) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "long position must be exercisable before expiration");
    }
}

// EIP-1271 signing maker: makes the order signature valid for any fuzzed signature bytes
contract Maker1271 {
    function isValidSignature(bytes32, bytes calldata) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

// Mock base-asset token: lets every transfer succeed so the fill/exercise flow runs
contract MockERC20 {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }
}
